// GPU bounds and ID mapping for every validated leaf side in a local sphere.
// The original data and the output are temporary and never enter the repo.
static void probe_sphere_sidecar(ID3D12Device5 *dev, ID3D12CommandQueue *queue, FILE *receipt) {
    std::ifstream available("sphere-sidecar-body.bin", std::ios::binary);
    if (!available) return;
    const auto body = read_file("sphere-sidecar-body.bin");
    const auto directory = read_file("sphere-sidecar-directory.bin");
    const auto expected = read_file("sphere-sidecar-expected.bin");
    struct Record { UINT geometry, primitive, leaf, side; float vertices[3][3]; };
    static_assert(sizeof(Record) == 52);
    if (body.empty() || directory.empty() || expected.empty() || expected.size() % sizeof(Record) != 0)
        throw std::runtime_error("invalid sphere sidecar files");
    const UINT count = static_cast<UINT>(expected.size() / sizeof(Record));
    const UINT bounds_bytes = count * sizeof(D3D12_RAYTRACING_AABB);
    const UINT map_bytes = count * 16;
    auto body_upload = upload(dev, body.data(), body.size());
    auto directory_upload = upload(dev, directory.data(), directory.size());
    auto body_gpu = buffer(dev, body.size(), D3D12_HEAP_TYPE_DEFAULT, D3D12_RESOURCE_STATE_COPY_DEST);
    auto directory_gpu = buffer(dev, directory.size(), D3D12_HEAP_TYPE_DEFAULT, D3D12_RESOURCE_STATE_COPY_DEST);
    auto bounds = buffer(dev, bounds_bytes, D3D12_HEAP_TYPE_DEFAULT, D3D12_RESOURCE_STATE_UNORDERED_ACCESS, true);
    auto mapping = buffer(dev, map_bytes, D3D12_HEAP_TYPE_DEFAULT, D3D12_RESOURCE_STATE_UNORDERED_ACCESS, true);
    auto bounds_status = buffer(dev, 4, D3D12_HEAP_TYPE_DEFAULT, D3D12_RESOURCE_STATE_COPY_DEST, true);
    auto map_status = buffer(dev, 4, D3D12_HEAP_TYPE_DEFAULT, D3D12_RESOURCE_STATE_COPY_DEST, true);
    const UINT zero = 0;
    auto zero_upload = upload(dev, &zero, 4);
    const UINT readback_bytes = bounds_bytes + map_bytes + 8;
    auto readback = buffer(dev, readback_bytes, D3D12_HEAP_TYPE_READBACK, D3D12_RESOURCE_STATE_COPY_DEST);
    D3D12_ROOT_PARAMETER params[5]{};
    params[0].ParameterType = D3D12_ROOT_PARAMETER_TYPE_SRV;
    params[1].ParameterType = D3D12_ROOT_PARAMETER_TYPE_UAV;
    params[2].ParameterType = D3D12_ROOT_PARAMETER_TYPE_UAV;
    params[2].Descriptor.ShaderRegister = 1;
    params[3].ParameterType = D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;
    params[3].Constants = {0, 0, 4};
    params[4].ParameterType = D3D12_ROOT_PARAMETER_TYPE_SRV;
    params[4].Descriptor.ShaderRegister = 1;
    D3D12_ROOT_SIGNATURE_DESC root_desc{5,params,0,nullptr,D3D12_ROOT_SIGNATURE_FLAG_NONE};
    ComPtr<ID3DBlob> blob;
    check(D3D12SerializeRootSignature(&root_desc,D3D_ROOT_SIGNATURE_VERSION_1,&blob,nullptr),"sphere sidecar root serialize");
    ComPtr<ID3D12RootSignature> root;
    check(dev->CreateRootSignature(0,blob->GetBufferPointer(),blob->GetBufferSize(),IID_PPV_ARGS(&root)),"sphere sidecar root");
    D3D12_COMPUTE_PIPELINE_STATE_DESC desc{};
    desc.pRootSignature = root.Get();
    desc.CS = {sidecar_bounds_dxil,sizeof(sidecar_bounds_dxil)};
    ComPtr<ID3D12PipelineState> bounds_pso, map_pso;
    check(dev->CreateComputePipelineState(&desc,IID_PPV_ARGS(&bounds_pso)),"sphere sidecar bounds pipeline");
    desc.CS = {sidecar_map_dxil,sizeof(sidecar_map_dxil)};
    check(dev->CreateComputePipelineState(&desc,IID_PPV_ARGS(&map_pso)),"sphere sidecar map pipeline");
    ComPtr<ID3D12CommandAllocator> allocator;
    ComPtr<ID3D12GraphicsCommandList> list;
    check(dev->CreateCommandAllocator(D3D12_COMMAND_LIST_TYPE_DIRECT,IID_PPV_ARGS(&allocator)),"sphere sidecar allocator");
    check(dev->CreateCommandList(0,D3D12_COMMAND_LIST_TYPE_DIRECT,allocator.Get(),nullptr,IID_PPV_ARGS(&list)),"sphere sidecar list");
    list->CopyBufferRegion(body_gpu.Get(),0,body_upload.Get(),0,body.size());
    list->CopyBufferRegion(directory_gpu.Get(),0,directory_upload.Get(),0,directory.size());
    list->CopyBufferRegion(bounds_status.Get(),0,zero_upload.Get(),0,4);
    list->CopyBufferRegion(map_status.Get(),0,zero_upload.Get(),0,4);
    D3D12_RESOURCE_BARRIER ready[4]{};
    for (auto &item : ready) item.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
    ready[0].Transition = {body_gpu.Get(),0,D3D12_RESOURCE_STATE_COPY_DEST,D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE};
    ready[1].Transition = {directory_gpu.Get(),0,D3D12_RESOURCE_STATE_COPY_DEST,D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE};
    ready[2].Transition = {bounds_status.Get(),0,D3D12_RESOURCE_STATE_COPY_DEST,D3D12_RESOURCE_STATE_UNORDERED_ACCESS};
    ready[3].Transition = {map_status.Get(),0,D3D12_RESOURCE_STATE_COPY_DEST,D3D12_RESOURCE_STATE_UNORDERED_ACCESS};
    list->ResourceBarrier(4,ready);
    list->SetComputeRootSignature(root.Get());
    list->SetComputeRootShaderResourceView(0,body_gpu->GetGPUVirtualAddress());
    list->SetComputeRootShaderResourceView(4,directory_gpu->GetGPUVirtualAddress());
    list->SetPipelineState(bounds_pso.Get());
    list->SetComputeRootUnorderedAccessView(1,bounds->GetGPUVirtualAddress());
    list->SetComputeRootUnorderedAccessView(2,bounds_status->GetGPUVirtualAddress());
    UINT sizes[]{static_cast<UINT>(body.size()),bounds_bytes,count,static_cast<UINT>(directory.size())};
    list->SetComputeRoot32BitConstants(3,4,sizes,0);
    list->Dispatch((count+63)/64,1,1);
    list->SetPipelineState(map_pso.Get());
    list->SetComputeRootUnorderedAccessView(1,mapping->GetGPUVirtualAddress());
    list->SetComputeRootUnorderedAccessView(2,map_status->GetGPUVirtualAddress());
    sizes[1] = map_bytes;
    list->SetComputeRoot32BitConstants(3,4,sizes,0);
    list->Dispatch((count+63)/64,1,1);
    D3D12_RESOURCE_BARRIER done[4]{};
    for (auto &item : done) item.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
    done[0].Transition = {bounds.Get(),0,D3D12_RESOURCE_STATE_UNORDERED_ACCESS,D3D12_RESOURCE_STATE_COPY_SOURCE};
    done[1].Transition = {mapping.Get(),0,D3D12_RESOURCE_STATE_UNORDERED_ACCESS,D3D12_RESOURCE_STATE_COPY_SOURCE};
    done[2].Transition = {bounds_status.Get(),0,D3D12_RESOURCE_STATE_UNORDERED_ACCESS,D3D12_RESOURCE_STATE_COPY_SOURCE};
    done[3].Transition = {map_status.Get(),0,D3D12_RESOURCE_STATE_UNORDERED_ACCESS,D3D12_RESOURCE_STATE_COPY_SOURCE};
    list->ResourceBarrier(4,done);
    list->CopyBufferRegion(readback.Get(),0,bounds.Get(),0,bounds_bytes);
    list->CopyBufferRegion(readback.Get(),bounds_bytes,mapping.Get(),0,map_bytes);
    list->CopyBufferRegion(readback.Get(),bounds_bytes+map_bytes,bounds_status.Get(),0,4);
    list->CopyBufferRegion(readback.Get(),bounds_bytes+map_bytes+4,map_status.Get(),0,4);
    submit(dev,queue,list.Get());
    D3D12_RANGE read{0,readback_bytes}, empty{};
    void *data{};
    check(readback->Map(0,&read,&data),"sphere sidecar readback");
    const auto *bytes = static_cast<const BYTE *>(data);
    UINT status[2]{};
    std::memcpy(status,bytes+bounds_bytes+map_bytes,sizeof(status));
    bool ok = status[0] == 0 && status[1] == 0;
    UINT paired = 0;
    for (UINT i=0;i<count;++i) {
        Record record{};
        D3D12_RAYTRACING_AABB box{};
        std::array<UINT,4> actual{};
        std::memcpy(&record,expected.data()+i*sizeof(record),sizeof(record));
        std::memcpy(&box,bytes+i*sizeof(box),sizeof(box));
        std::memcpy(actual.data(),bytes+bounds_bytes+i*16,16);
        ok &= actual == std::array<UINT,4>{record.geometry,record.primitive,record.leaf,record.side};
        paired += record.side == 1;
        const float lo[]{box.MinX,box.MinY,box.MinZ}, hi[]{box.MaxX,box.MaxY,box.MaxZ};
        for (UINT axis=0;axis<3;++axis) for (auto &vertex : record.vertices)
            ok &= std::isfinite(lo[axis]) && std::isfinite(hi[axis]) && lo[axis] < vertex[axis] && hi[axis] > vertex[axis];
    }
    readback->Unmap(0,&empty);
    std::fprintf(receipt,"sphere_sidecar=count %u; second_sides %u; bounds_status %u; map_status %u; matched %u\n",
                 count,paired,status[0],status[1],ok);
    if (!ok || !paired) throw std::runtime_error("sphere sidecar mapping or bounds mismatch");
}
